function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const sections = plain(Inputs.sections) || [];
if (!sections.length) return;
const extra = {
  id: 'pal-artifact',
  kind: 'artifact_challenge',
  title: 'Bring back one cleaned row',
  brief: 'Take one real row from intake.csv, run it through your sanitiser, and paste what came out beside what went in.',
  rubric: ['The row you chose is one a colleague actually sent', 'Every rule you wrote is visible in the difference', 'You can say which rule you are least sure about'],
  acceptedFormats: ['text', 'markdown']
};
Outputs.rows = sections.concat([extra]).map((s) => ({ id: s.id, section: s }));

// The page title is the browser TAB, and it is the one learner-facing string a
// Translation node cannot reach: `Page.title` is read off the node's PARAMETERS at
// export time into the router index (utils/exporter/router.ts), and the Router hands
// that to Noodl.SEO.setTitle on mount. A connection to the port is silently ignored —
// measured, TASK-L161 §1: with the parameter removed and a Translation wired, the tab
// read "Home", the component name.
//
// So the parameter stays as the BUILD-TIME FALLBACK (the router index needs it, and it
// is what the tab shows for the instant before this runs), and the translated value
// overrides it here. Same shape as the kit's built-in English: a fallback is not a
// second owner.
const t = Inputs.title;
if (typeof t === 'string' && t !== '' && typeof Noodl !== 'undefined' && Noodl.SEO) {
  Noodl.SEO.setTitle(t);
}
